sp_widget.client_script:
api.controller = function($scope, $sce) {

    console.log("Client loaded ✅");

    $scope.searchText = "";

    // ✅ default
    if ($scope.data.articles && $scope.data.articles.length > 0) {
        setSelected($scope.data.articles[0]);
    }

    function setSelected(article) {
        $scope.selectedArticle = article;
        $scope.trustedText = $sce.trustAsHtml(article.text); // ✅ separate variable
    }

    // ✅ click
    $scope.selectArticle = function(article) {
        setSelected(article);
    };

};

sp_widget.css:
.kb-wrapper {
  display: flex;
  height: 100%;
  border: 1px solid #ddd;
  background: #fff;
}

/* LEFT PANEL */
.kb-left {
  width: 30%;
  border-right: 1px solid #ddd;
  background: #fafafa;
  display: flex;
  flex-direction: column;
}

/* Search */
.kb-search {
  padding: 10px;
  border-bottom: 1px solid #ddd;
}

/* No results */
.no-results {
  padding: 10px;
  color: #888;
  font-style: italic;
}

/* List */
.kb-list {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
}

.kb-list li {
  padding: 10px;
  cursor: pointer;
  border-bottom: 1px solid #eee;
  transition: background 0.2s;
}

.kb-list li:hover {
  background: #f1f1f1;
}

/* ✅ Highlight FIX */
.kb-list li.active {
  background-color: #007bff;
  color: white;
  font-weight: bold;
}

/* RIGHT */
.kb-right {
  width: 70%;
  padding: 20px;
  overflow-y: auto;
}

/* Header */
.kb-header {
  border-bottom: 2px solid #eee;
  margin-bottom: 15px;
}

.kb-number {
  color: #777;
  font-size: 13px;
}

/* Content */
.kb-content {
  line-height: 1.6;
}
``

sp_widget.script:
(function() {

    data.articles = [];

    var gr = new GlideRecord('kb_knowledge');
    gr.addEncodedQuery('kb_knowledge_base=76080c0b83c503d0f595ffd6feaad3dd');
    gr.orderBy('short_description');
    gr.setLimit(50);
    gr.query();

    while (gr.next()) {
        data.articles.push({
            sys_id: gr.getUniqueValue(),
            number: gr.number.toString(),
            title: gr.short_description.toString(),
            text: gr.text.toString()
        });
    }

})();
